namespace Pragmatic.Validation;

/// <summary>
///     Provides metadata about which async validators should be invoked
///     based on modified properties. Generated by the source generator
///     from <c>[AsyncValidate&lt;T&gt;]</c> attribute bindings.
/// </summary>
/// <remarks>
///     <para>
///         This interface is implemented by generated binding classes that map
///         async validators to their trigger properties (or entity-level triggers).
///     </para>
///     <para>
///         Used by <see cref="CompositeValidator{T}" /> to filter which async validators
///         to invoke during change-aware validation.
///     </para>
///     <para>
///         Trigger semantics:
///         <list type="bullet">
///             <item><c>modifiedProperties = null</c> (create mode) → always returns <c>true</c> for bound validators</item>
///             <item>Entity-level binding → always returns <c>true</c> regardless of which properties changed</item>
///             <item>Property-level binding → returns <c>true</c> only if the trigger property is in <c>modifiedProperties</c></item>
///             <item>Unknown validator (not bound) → returns <c>false</c></item>
///         </list>
///     </para>
/// </remarks>
/// <typeparam name="T">The entity type that owns the bindings.</typeparam>
public interface IAsyncValidatorBindings<T>
{
    /// <summary>
    ///     Determines whether the given async validator should be invoked
    ///     based on the set of modified properties.
    /// </summary>
    /// <param name="validatorType">The concrete type of the async validator.</param>
    /// <param name="modifiedProperties">
    ///     The set of modified property names, or <c>null</c> for create mode (validates all).
    /// </param>
    /// <returns>
    ///     <c>true</c> if the validator should be invoked; <c>false</c> to skip it.
    /// </returns>
    bool ShouldInvoke(Type validatorType, IReadOnlySet<string>? modifiedProperties);
}
